import{_ as t,o as a,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Developer Monthly Meetup EMEA - April 2026","description":"","frontmatter":{"title":"Ceph Developer Monthly Meetup EMEA - April 2026","date":"2026-04-08T00:00:00.000Z","updated":"2026-04-09T00:00:00.000Z","tags":["Ceph","升级测试","OSD","cephadm","开发者会议"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Developer_Monthly_Meetup_EMEA_-_April_2026.md","filePath":"posts/2026/Ceph_Developer_Monthly_Meetup_EMEA_-_April_2026.md","lastUpdated":1780459816000}'),o={name:"posts/2026/Ceph_Developer_Monthly_Meetup_EMEA_-_April_2026.md"};function i(d,e,p,n,h,s){return a(),l("div",null,[...e[0]||(e[0]=[r('<h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 Ceph Developer Monthly Meetup EMEA（2026 年 4 月）为临时性会议，议程中原本没有预设议题。主持人开放自由讨论，最终围绕 Umbrella 升级工作的测试状态展开了一次有价值的技术交流。</p><h2 id="主要议题-umbrella-升级测试失败问题" tabindex="-1">主要议题：Umbrella 升级测试失败问题 <a class="header-anchor" href="#主要议题-umbrella-升级测试失败问题" aria-label="Permalink to &quot;主要议题：Umbrella 升级测试失败问题&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>Umbrella 升级的 kickoff PR 已经合并，但合并时升级测试（upgrade tests）大量失败。团队在明知测试未通过的情况下仍选择合并，计划后续跟进修复。</p><h3 id="失败原因分析" tabindex="-1">失败原因分析 <a class="header-anchor" href="#失败原因分析" aria-label="Permalink to &quot;失败原因分析&quot;">​</a></h3><p>与会者 Alex 分享了当天早上触发的测试运行结果，界面呈现&quot;一片红色&quot;。经过讨论，失败原因主要分为以下几类：</p><p><strong>1. Health Warning 导致的失败（主要原因）</strong></p><p>大多数测试失败源于集群日志中出现的 health warning。测试框架在每个测试结束前会执行一次集群健康检查（cluster badness check），即便 health warning 是瞬时出现的，也会导致测试标记为失败。</p><p>重要说明：这类失败并不意味着升级本身未完成，只是测试在升级完成后检测到了 health warning。这属于&quot;令人烦恼&quot;而非&quot;令人恐慌&quot;的问题。</p><p>具体出现的 health warning 包括：</p><ul><li>集群日志中出现 quota 耗尽（running out of quota）</li><li>pool full 警告</li></ul><p><strong>2. Umbrella 特有问题（已基本修复）</strong></p><ul><li>cephos 软件包的 RBM 重命名导致的若干问题</li><li>某命令新增参数导致 cephadm 解析失败</li></ul><p>上述问题均已开 tracker 并修复。</p><p><strong>3. 残留问题</strong></p><ul><li>仍有少量测试在尝试安装 cephos-d Classic时失败，需进一步排查</li><li>存在少量 stuck PG 现象</li></ul><h3 id="应对策略" tabindex="-1">应对策略 <a class="header-anchor" href="#应对策略" aria-label="Permalink to &quot;应对策略&quot;">​</a></h3><p><strong>短期行动：</strong></p><ul><li>Alex 将在 Ceph core team 内部频道发起协作，招募有带宽的成员共同 review 本次测试运行结果</li><li>对所有失败项进行 triage，确保每类问题都有对应 tracker</li><li>参考此前 Rocky 10 工作中建立 baseline 的经验，建立升级测试的稳定 baseline</li></ul><p><strong>中期目标：</strong></p><ul><li>自实验室迁移以来，升级测试缺乏持续的 baseline 调度，需要恢复定期运行机制</li><li>针对 cephadm failed daemon 问题，需联系 cephadm 团队跟进，该问题目前尚未有人认领解决</li></ul><p><strong>已知修复可用：</strong></p><ul><li>cephos-d Classic 安装失败问题此前在 encoder 测试中已有修复方案，可直接应用到升级测试中</li></ul><h2 id="工具分享" tabindex="-1">工具分享 <a class="header-anchor" href="#工具分享" aria-label="Permalink to &quot;工具分享&quot;">​</a></h2><p>Alex 提到，他在使用 IBM watsonx Code Assistant（基于 Claude Code）辅助分析大量测试日志，取得了较好的效果，在定位有效调试信息方面命中率较高，显著提升了日志分析效率。</p><ul><li>IBM内部用户可直接使用 IBM watsonx Code Assistant（需有许可证）</li><li>外部用户可考虑使用 Claude Code 等类似代码助手产品</li><li>有兴趣了解具体 prompt 策略的人员可直接联系 Alex</li></ul><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><table tabindex="0"><thead><tr><th>行动项</th><th>负责人</th><th>状态</th></tr></thead><tbody><tr><td>在 core team 频道发起升级测试 review 协作</td><td>Alex</td><td>待执行</td></tr><tr><td>Review 本次测试运行，确保所有失败项有 tracker</td><td>Core team 志愿者</td><td>待认领</td></tr><tr><td>跟进 cephadm failed daemon 问题</td><td>Alex / cephadm 团队</td><td>待联系</td></tr><tr><td>排查残留的 cephos-d Classic 安装失败</td><td>Alex</td><td>进行中</td></tr><tr><td>恢复升级测试定期 baseline 调度</td><td>Core team</td><td>待规划</td></tr></tbody></table><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本次会议虽为临时召开，但围绕 Umbrella 升级测试的讨论颇具实质性价值。核心结论是：当前大量测试失败主要由 health warning 机制触发，并非升级流程本身存在根本性问题。团队将通过协作 triage、建立 baseline 和跟进专项问题等方式逐步稳定测试结果。</p>',31)])])}const _=t(o,[["render",i]]);export{c as __pageData,_ as default};
